from build import S,lesson as L


def lessons():
 result=[
 L('tensors','Tensor creation, shape, and dtype','Tensors combine values with shape, dtype, and device. Explicitly distinguish floating tensors used for differentiable operations from integer tensors used for indices. Print lists or scalar items for stable examples. No GPU is required for these exercises.',
 S('x=torch.tensor([[${n},0],[${m},1]])\nprint(~tuple(x.shape)~)','(2, 2)','(4,)|(2,)','The nested input creates two rows and two columns.','x.numel()|x.ndim'),
 S('x=torch.zeros((2,${m}))\nprint(~x.numel()~)','${twom}','2|${m}','numel counts every tensor element.','x.ndim|tuple(x.shape)'),
 S('x=torch.tensor([${n}],dtype=~torch.float32~)\nprint(x.dtype)','torch.float32','torch.int64|torch.bool','The explicit dtype selects floating-point storage.','torch.int64|torch.bool'),
 S('x=torch.tensor(${n})\nprint(~x.item()~)','${n}','[${n}]|RuntimeError','item extracts a Python number from a one-element tensor.','x.tolist()+1|x.numel()')),
 L('shapes','Views, reshaping, and axis movement','reshape changes shape while preserving element count and may copy. view requires a compatible layout. transpose swaps selected axes; permute gives a complete axis order. contiguous can materialize a contiguous layout after a permutation.',
 S('x=torch.arange(6)\nprint(tuple(x.reshape(~2,3~).shape))','(2, 3)','(3, 2)|(6,)','The new shape retains all six elements.','3,2|6'),
 S('x=torch.zeros((2,3))\nprint(tuple(x.transpose(~0,1~).shape))','(3, 2)','(2, 3)|(6,)','transpose exchanges the two axes.','0,0|1,1'),
 S('x=torch.zeros((2,3,4))\nprint(tuple(x.permute(~2,0,1~).shape))','(4, 2, 3)','(2, 3, 4)|(3, 2, 4)','permute lists the old axis at each new position.','0,1,2|1,0,2'),
 S('x=torch.zeros((2,3)).t()\nprint(x.~contiguous()~.is_contiguous())','True','False|RuntimeError','contiguous returns a contiguous representation, copying when necessary.','transpose(0,0)|detach()')),
 L('indexing','Indexing and batch-preserving operations','An integer index removes an axis; a slice preserves it. unsqueeze adds a singleton axis, and squeeze removes selected singleton dimensions. Avoid an unrestricted squeeze when a batch of one must retain its batch axis.',
 S('x=torch.tensor([[${n},0],[${m},1]])\nprint(x[~1,0~].item())','${m}','${n}|1','Select row one and column zero.','0,0|1,1'),
 S('x=torch.zeros((1,3))\nprint(tuple(x[~0:1~].shape))','(1, 3)','(3,)|(0, 3)','A slice preserves the leading batch dimension.','0|1:2'),
 S('x=torch.zeros(3)\nprint(tuple(x.~unsqueeze(0)~.shape))','(1, 3)','(3, 1)|(3,)','unsqueeze inserts a length-one dimension at the specified position.','unsqueeze(1)|clone()'),
 S('x=torch.zeros((1,3,1))\nprint(tuple(x.~squeeze(-1)~.shape))','(1, 3)','(3,)|(3, 1)','Squeezing only the final axis preserves the batch dimension.','squeeze()|squeeze(0)')),
 L('operations','Broadcasting and reductions','Elementwise operations align shapes from the right, with singleton dimensions expanding. dim chooses the axis for reductions. keepdim preserves a length-one axis. Matrix multiplication has different shape rules from elementwise multiplication.',
 S('x=torch.zeros((2,3)); bias=torch.ones(3)\nprint(tuple((~x+bias~).shape))','(2, 3)','(3, 2)|RuntimeError','A feature vector broadcasts across two rows.','x.t()+bias[:,None]|bias'),
 S('x=torch.tensor([[${n},0],[${m},1]])\nprint(x.sum(dim=~0~).tolist())','[${add}, 1]','[${n}, ${mnext}]|${add1}','Reducing the row axis leaves one total per column.','1|None'),
 S('x=torch.zeros((2,3))\nprint(tuple(x.sum(dim=1,keepdim=~True~).shape))','(2, 1)','(2,)|(1, 3)','keepdim retains the reduced axis.','False|None'),
 S('a=torch.ones((2,3)); b=torch.ones((3,4))\nprint(tuple((a~@~b).shape))','(2, 4)','(2, 3)|RuntimeError','Matrix multiplication contracts the inner dimension.','*|+')),
 L('autograd','Autograd graphs and leaf gradients','requires_grad enables recording for suitable floating/complex tensors. backward computes gradients and accumulates them in leaf .grad fields. A scalar loss needs no explicit gradient argument. These exercises inspect API behavior rather than deriving an optimization algorithm.',
 S('x=torch.tensor(float(${n}),requires_grad=~True~)\ny=x*2; y.backward()\nprint(x.grad.item())','2.0','${double}.0|None','The scalar multiplication produces a gradient of two for this leaf.','False|None'),
 S('x=torch.tensor(float(${n}),requires_grad=True)\n(x*2).backward(); (x*3).backward()\nprint(~x.grad.item()~)','5.0','3.0|2.0','Gradients accumulate across backward calls unless cleared.','x.item()|x.numel()'),
 S('x=torch.tensor(float(${n}),requires_grad=True)\n(x*2).backward()\nx.grad=~None~\nprint(x.grad is None)','True','False|RuntimeError','Setting grad to None removes the accumulated gradient for the next computation.','torch.zeros_like(x)|x'),
 S('x=torch.tensor(float(${n}),requires_grad=True)\ny=x*2\nprint(~y.requires_grad~)','True','False|None','An operation involving a tracked input produces a tracked result here.','y.is_leaf|x.grad is not None')),
 L('storage','Detach, clone, and storage sharing','detach disconnects autograd history but shares storage. clone copies data and can still participate in autograd. detach().clone() gives an independent untracked snapshot. Understand aliasing before in-place updates, especially when autograd has saved values.',
 S('x=torch.tensor([float(${n})],requires_grad=True)\ny=x.~detach()~\nprint(y.requires_grad)','False','True|RuntimeError','detach removes graph tracking for this result.','clone()|reshape(1)'),
 S('x=torch.tensor([${n}]); y=x.~detach()~; y[0]=0\nprint(x.item())','0','${n}|RuntimeError','Detaching does not copy the backing storage.','clone()|detach().clone()'),
 S('x=torch.tensor([${n}]); y=x.~clone()~; y[0]=0\nprint(x.item())','${n}','0|RuntimeError','clone creates independent data.','detach()|view(1)'),
 S('x=torch.tensor([float(${n})],requires_grad=True)\ny=x.~detach().clone()~\nprint(y.requires_grad, y.data_ptr()==x.data_ptr())','False False','False True|True False','The combination disconnects the graph and allocates separate storage.','detach()|clone()')),
 L('modules','Modules, parameters, and forward calls','nn.Module registers parameters and child modules assigned as attributes. Calling model(x) invokes the module call machinery around forward. Linear maps the final feature dimension; its weight shape is out_features by in_features. Registered state drives optimization and saving.',
 S('layer=torch.nn.Linear(3,${m})\nx=torch.zeros((2,3))\nprint(tuple(~layer(x)~.shape))','(2, ${m})','(${m}, 2)|(2, 3)','Linear replaces the final feature dimension with out_features.','layer.weight|x'),
 S('layer=torch.nn.Linear(3,${m})\nprint(tuple(layer.~weight~.shape))','(${m}, 3)','(3, ${m})|(${m},)','The weight stores one row per output feature.','bias|weight.t()'),
 S('layer=torch.nn.Linear(3,2,bias=~False~)\nprint(len(list(layer.parameters())))','1','2|0','With no bias, only the weight parameter is registered.','True|None'),
 S('model=torch.nn.Sequential(torch.nn.Linear(3,2),torch.nn.ReLU())\nprint(tuple(~model(torch.zeros((4,3)))~.shape))','(4, 2)','(4, 3)|(2, 4)','Sequential applies each registered module in order.','model[0].weight|torch.zeros((3,4))')),
 L('modes','Training mode versus gradient recording','eval changes training-sensitive modules such as Dropout and BatchNorm. It does not disable autograd. no_grad disables recording in its block; inference_mode is a stronger inference context with additional tensor restrictions. Choose mode and gradient policy separately.',
 S('model=torch.nn.Dropout(p=0.5)\nmodel.~eval()~\nprint(model.training)','False','True|RuntimeError','eval sets training=False for the module and its children.','train()|requires_grad_(False)'),
 S('model=torch.nn.Identity().eval()\nx=torch.tensor(float(${n}),requires_grad=True)\ny=model(x)*2\nprint(~y.requires_grad~)','True','False|None','Evaluation mode alone does not turn off autograd.','y.is_leaf|x.grad is not None'),
 S('x=torch.tensor(float(${n}),requires_grad=True)\nwith torch.~no_grad~():\n    y=x*2\nprint(y.requires_grad)','False','True|RuntimeError','no_grad suppresses recording for the multiplication.','enable_grad|set_default_device'),
 S('drop=torch.nn.Dropout(p=1.0)\n~drop.eval()~\nprint(drop(torch.tensor([float(${n})])).tolist())','[${n}.0]','[0.0]|RuntimeError','Dropout acts as identity in evaluation mode.','drop.train()|drop.requires_grad_(False)')),
 L('data','Datasets, batches, and loader contracts','A Dataset provides examples; DataLoader groups them into batches and can shuffle. drop_last discards a short final batch. Shuffle affects order, not the total number of examples. Use deterministic shapes and explicit seeds when testing input pipelines.',
 S('data=torch.utils.data.TensorDataset(torch.arange(${n}))\nprint(~len(data)~)','${n}','1|0','TensorDataset length follows the shared first dimension of its tensors.','len(data.tensors)|len(data[0])'),
 S('loader=torch.utils.data.DataLoader(torch.arange(5),batch_size=~2~,shuffle=False)\nprint([len(batch) for batch in loader])','[2, 2, 1]','[2, 2]|[5]','The final batch retains the remaining example by default.','5|1'),
 S('loader=torch.utils.data.DataLoader(torch.arange(5),batch_size=2,drop_last=~True~)\nprint([len(batch) for batch in loader])','[2, 2]','[2, 2, 1]|[5]','drop_last removes the incomplete final batch.','False|None'),
 S('loader=torch.utils.data.DataLoader(torch.arange(5),batch_size=2,shuffle=~False~)\nprint(next(iter(loader)).tolist())','[0, 1]','[3, 4]|[0, 1, 2, 3, 4]','Without shuffling the first batch follows dataset order.','True|None')),
 L('optimization','Reading a training step','A typical step clears old gradients, runs forward, computes a scalar loss, calls backward, then updates parameters with optimizer.step. backward alone does not change parameter values. The exercise focuses on state transitions and code order, not optimization theory.',
 S('p=torch.nn.Parameter(torch.tensor(float(${n})))\nopt=torch.optim.SGD([p],lr=1.0)\n(p*2).backward(); opt.~step()~\nprint(p.item())','${nminus2}.0','${n}.0|2.0','step applies the accumulated gradient update; here a unit learning rate subtracts two.','zero_grad()|state_dict()'),
 S('p=torch.nn.Parameter(torch.tensor(float(${n})))\n(p*2).backward()\nprint(~p.item()~)','${n}.0','${nminus2}.0|2.0','backward records a gradient without updating the parameter itself.','p.grad.item()|p.numel()'),
 S('p=torch.nn.Parameter(torch.tensor(float(${n})))\nopt=torch.optim.SGD([p],lr=1.0)\n(p*2).backward(); opt.~zero_grad~(set_to_none=True)\nprint(p.grad is None)','True','False|RuntimeError','Clearing gradients prevents unintentional accumulation into the next step.','step|add_param_group'),
 S('prediction=torch.tensor([float(${n})]); target=prediction.clone()\nloss=torch.nn.functional.~mse_loss~(prediction,target)\nprint(loss.item())','0.0','1.0|RuntimeError','Matching prediction and target have zero mean squared error.','cross_entropy|cosine_similarity')),
 L('devices','Device and dtype boundaries','Tensor.to returns the converted tensor; assign its result when needed. Inputs and parameters must use compatible devices and dtypes for operations. For NumPy conversion, detach gradients and move to CPU first. non_blocking transfer is not a universal promise of overlap.',
 S('x=torch.tensor([${n}],dtype=torch.int64)\ny=x.to(dtype=~torch.float32~)\nprint(y.dtype)','torch.float32','torch.int64|torch.bool','The requested conversion returns a float tensor.','torch.int64|torch.bool'),
 S('x=torch.tensor([${n}],dtype=torch.int64)\nx.to(torch.float32)\nprint(~x.dtype~)','torch.int64','torch.float32|RuntimeError','Ignoring the converted result leaves x bound to the original tensor.','x.shape|x.numel()'),
 S('x=torch.tensor([float(${n})],requires_grad=True)\na=x.~detach().cpu().numpy()~\nprint(a.tolist())','[${n}.0]','RuntimeError|[0.0]','Detach and CPU conversion satisfy the normal NumPy conversion requirements.','numpy()|cpu().numpy()'),
 S('x=torch.tensor([${n}],device=~"cpu"~)\nprint(x.device.type)','cpu','cuda|RuntimeError','This explicit device works without a GPU.','"cuda"|"meta"')),
 L('checkpoints','State dictionaries and inference checkpoints','state_dict includes registered parameters and persistent buffers. Its tensors are not automatically an independent snapshot, so copy or serialize when preserving a point in time. Load into a compatible architecture and set evaluation mode explicitly for inference. Use weights_only loading for tensor-oriented checkpoints.',
 S('layer=torch.nn.Linear(3,2)\nstate=layer.~state_dict()~\nprint(sorted(state.keys()))',"['bias', 'weight']", "['training']|[]",'The state dictionary exposes the registered weight and bias.','named_parameters()|parameters()'),
 S('a=torch.nn.Linear(3,2); b=torch.nn.Linear(3,2)\nb.~load_state_dict~(a.state_dict())\nprint(torch.equal(a.weight,b.weight))','True','False|RuntimeError','Loading compatible state copies the learned tensor values into b.','register_buffer|add_module'),
 S('import io\nbuf=io.BytesIO(); torch.save({"x":torch.tensor([${n}])},buf); buf.seek(0)\nstate=torch.load(buf,weights_only=~True~)\nprint(state["x"].item())','${n}','0|RuntimeError','The tensor-only payload can be loaded with the restricted weights-only path.','None|"True"'),
 S('model=torch.nn.Linear(3,2)\nmodel.load_state_dict(model.state_dict())\nprint(~model.training~)','True','False|None','Loading weights does not switch a freshly created module out of training mode.','not model.training|model.bias is None')),
 ]
 return result
